 953→    // --- 6C-extra: Install success but not on PATH ---
 954→
 955→    #[test]
 956→    fn missing_install_success_but_not_on_path() {
 957→        // Scenario: A requirement is Missing, the user confirms install,
 958→        // the install command exits 0 (success), but after invalidating
 959→        // cache and re-checking, the tool is STILL not found on PATH.
 960→        // Expected: Outcome::Skip with message containing "may need shell restart".
 961→        //
 962→        // We use a custom requirement registered via with_custom whose check
 963→        // command always fails ("false"), so after install + re-check the
 964→        // tool remains missing.
 965→        use crate::config::{CustomRequirement, CustomRequirementCheck};
 966→        use std::collections::HashMap;
 967→
 968→        let mut custom = HashMap::new();
 969→        custom.insert(
 970→            "phantom-tool".to_string(),
 971→            CustomRequirement {
 972→                check: CustomRequirementCheck::CommandSucceeds {
 973→                    command: "false".to_string(),
 974→                },
 975→                install_template: Some("phantom-install".to_string()),
 976→                install_hint: Some("install-phantom-tool".to_string()),
 977→            },
 978→        );
 979→
 980→        let registry = RequirementRegistry::new().with_custom(&custom);
 981→        let probe = make_probe();
 982→        let temp = TempDir::new().unwrap();
 983→        let mut checker = make_checker(&registry, &probe, &temp);
 984→        let mut ui = MockUI::new();
 985→        ui.set_interactive(true);
 986→        ui.set_prompt_response("install_phantom-tool", "yes");
 987→
 988→        // run_command returns true (install "succeeds" exit 0),
 989→        // but network is available and the check still fails after install
 990→        let ctx = stub_ctx(true, true);
 991→
 992→        let gaps = vec![GapResult {
 993→            requirement: "phantom-tool".to_string(),
 994→            status: RequirementStatus::Missing {
 995→                install_template: Some("phantom-install".to_string()),
 996→                install_hint: Some("install-phantom-tool".to_string()),
 997→            },
 998→        }];
 999→
1000→        let result = handle_gaps(&gaps, &mut checker, &mut ui, true, &ctx);
1001→        // Should skip (not error) because install exited 0 but tool not found
1002→        assert!(!result.unwrap(), "should return false (skip)");
1003→        assert!(
1004→            ui.has_warning("not found on PATH")
1005→                || ui.has_warning("may need shell restart")
1006→                || ui.has_warning("May need shell restart"),
1007→            "should warn about PATH or shell restart, warnings: {:?}",
1008→            ui.warnings()
1009→        );
1010→    }
